import{_ as r,C as o,o as s,c as i,aj as t,E as n}from"./framework.js";const f=JSON.parse('{"title":"Dashboard | Site | Admin CMS","description":"The dashboard is the default landing page inside a site admin. It gives you a quick overview of site resources, traffic, and recent work, and links you into the most common CMS areas.","frontmatter":{"title":"Dashboard | Site | Admin CMS","description":"The dashboard is the default landing page inside a site admin. It gives you a quick overview of site resources, traffic, and recent work, and links you into the most common CMS areas.","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/site/dashboard.html"}]]},"headers":[],"relativePath":"cms/site/dashboard.md","filePath":"en/cms/site/dashboard.md","lastUpdated":1781010536000}'),d={name:"cms/site/dashboard.md"};function h(c,e,l,u,m,p){const a=o("DocImage");return s(),i("div",null,[e[0]||(e[0]=t('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><blockquote><p>Menu: top-left <strong>Home</strong> after entering a site<br> Deep link: <code>/_Admin/site?SiteId={siteGuid}</code></p></blockquote><p>The dashboard is the default landing page inside a site admin. It gives you a quick overview of site resources, traffic, and recent work, and links you into the most common CMS areas.</p><div class="tip custom-block"><p class="custom-block-title">Prerequisite</p><p>You should already have completed <a href="./../getting-started/login-and-site-list.html">Login and site list</a> and entered a site.</p></div><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><ol><li>In <strong>My Sites</strong>, click <strong>Manage</strong> for a site.</li><li>The URL is <code>/_Admin/site?SiteId=...</code>.</li><li>Use the <strong>Home</strong> icon in the left toolbar any time you want to return here.</li></ol>',6)),n(a,{src:"/cms/site/dashboard.png",alt:"Dashboard overview",width:"1120"}),e[1]||(e[1]=t('<h2 id="main-areas" tabindex="-1">Main areas <a class="header-anchor" href="#main-areas" aria-label="Permalink to &quot;Main areas&quot;">​</a></h2><h3 id="recent-visits" tabindex="-1">Recent visits <a class="header-anchor" href="#recent-visits" aria-label="Permalink to &quot;Recent visits&quot;">​</a></h3><p>Shows the admin pages you opened recently, so you can jump back into tasks such as basic settings, product management, or domain management.</p><h3 id="my-resources" tabindex="-1">My resources <a class="header-anchor" href="#my-resources" aria-label="Permalink to &quot;My resources&quot;">​</a></h3><p>Summarizes resource counts and storage usage across the current site.</p><table tabindex="0"><thead><tr><th>Common type</th><th>Meaning</th></tr></thead><tbody><tr><td>Pages</td><td>Number of pages in the site</td></tr><tr><td>Views</td><td>Reusable view components</td></tr><tr><td>Content</td><td>Content entries</td></tr><tr><td>Code</td><td>CodeBlock and related resources</td></tr><tr><td>Images</td><td>Media library assets</td></tr><tr><td>Scripts / Styles</td><td>Site-level JS and CSS resources</td></tr></tbody></table><h3 id="traffic-overview" tabindex="-1">Traffic overview <a class="header-anchor" href="#traffic-overview" aria-label="Permalink to &quot;Traffic overview&quot;">​</a></h3><p>The chart shows page-view trends for a recent time range. For deeper analytics, open <a href="./../operations/visitor-logs.html">Visitor logs</a>.</p><h3 id="hot-pages-and-hot-referrers" tabindex="-1">Hot pages and hot referrers <a class="header-anchor" href="#hot-pages-and-hot-referrers" aria-label="Permalink to &quot;Hot pages and hot referrers&quot;">​</a></h3><ul><li><strong>Hot pages</strong> ranks the most-visited page paths.</li><li><strong>Hot referrers</strong> shows where visitors came from.</li></ul><h3 id="recent-edits" tabindex="-1">Recent edits <a class="header-anchor" href="#recent-edits" aria-label="Permalink to &quot;Recent edits&quot;">​</a></h3><p>Lists objects changed recently in the admin so you can continue unfinished work.</p><h3 id="site-information" tabindex="-1">Site information <a class="header-anchor" href="#site-information" aria-label="Permalink to &quot;Site information&quot;">​</a></h3><p>Shows the current site name, type, creation time, bound domains, and authorized users. Detailed configuration still happens under <strong>Settings</strong>.</p><h3 id="docs-and-product-news" tabindex="-1">Docs and product news <a class="header-anchor" href="#docs-and-product-news" aria-label="Permalink to &quot;Docs and product news&quot;">​</a></h3><p>Provides links to Kooboo documentation and product updates. These are informational and not part of site configuration.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>On the dashboard</th><th>Read next</th></tr></thead><tbody><tr><td>My resources -&gt; Pages / Views</td><td><a href="./pages.html">Pages</a></td></tr><tr><td>My resources -&gt; Images</td><td><a href="./media.html">Media library</a></td></tr><tr><td>My resources -&gt; Content</td><td><a href="./../content/">Content</a></td></tr></tbody></table>',18))])}const b=r(d,[["render",h]]);export{f as __pageData,b as default};
